async function groupDiagnostics(p){ await p.evaluate(async()=>{window.groupAdmissionErrors=[];const {Engine}=await import('/assets/engine.mjs');for(const method of ['publishGroupInvitation','publishGroupPacket']){const call=Engine.prototype[method];Engine.prototype[method]=async function(...args){window.groupFixtureEngine=this;try{return await call.apply(this,args);}catch(err){window.groupAdmissionErrors.push({method,reason:err.reason,message:err.message});throw err;}};}const original=Engine.prototype.admitGroupLifecycle;Engine.prototype.admitGroupLifecycle=async function(...args){window.groupFixtureEngine=this;try{return await original.apply(this,args);}catch(err){window.groupAdmissionErrors.push({sub:args[0].sub,reason:err.reason,message:err.message});throw err;}};});}
